[CmdletBinding(SupportsShouldProcess=$true)]
param(
 [ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',
 [ValidateRange(1,20)][int]$RunsPerArm=5,
 [ValidateRange(30,600)][int]$SampleSeconds=120,
 [ValidateRange(1,10)][int]$SampleIntervalSeconds=2,
 [switch]$AllowAutomaticReboot,
 [string]$EvidenceRoot="$PSScriptRoot\lab-evidence",
 [string]$RunDirectory,
 [string]$ProviderPath="$PSScriptRoot\..\..\controller\providers\LogiTuneDemandLaunch.ps1"
)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
$Experiment='EXP-052';$TaskName='Lacksan-EXP-052-LabHarness';$ActivePointer=Join-Path $EvidenceRoot 'active.json'
function Elevation{$p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());if(!$p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required.'}}
function Ensure([string]$p){if(!(Test-Path -LiteralPath $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null}}
function WJ([string]$p,$v){$v|ConvertTo-Json -Depth 20|Set-Content -LiteralPath $p -Encoding UTF8}
function RJ([string]$p){if(!(Test-Path -LiteralPath $p)){throw "Required state missing: $p"};Get-Content -LiteralPath $p -Raw|ConvertFrom-Json}
function BootUtc{((Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime()}
function Med($v){$a=@($v|Where-Object{$null-ne$_}|ForEach-Object{[double]$_}|Sort-Object);if(!$a.Count){return $null};$m=[int][math]::Floor($a.Count/2);if($a.Count%2){return $a[$m]};($a[$m-1]+$a[$m])/2}
function Mad($v){$a=@($v|Where-Object{$null-ne$_}|ForEach-Object{[double]$_});if(!$a.Count){return $null};$m=Med $a;Med @($a|ForEach-Object{[math]::Abs($_-$m)})}
function Paths($d){[pscustomobject]@{Harness=Join-Path $d 'harness-state.json';Provider=Join-Path $d 'provider-state.json';ProviderLog=Join-Path $d 'provider-events.jsonl';Summary=Join-Path $d 'summary.json'}}
function Dir{if($RunDirectory){return(Resolve-Path -LiteralPath $RunDirectory).Path};$a=RJ $ActivePointer;(Resolve-Path -LiteralPath ([string]$a.runDirectory)).Path}
function Log($d,$e,$r,$data){[ordered]@{schemaVersion=1;timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment=$Experiment;component='lab-harness';action=$Action;event=$e;result=$r;machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;data=$data}|ConvertTo-Json -Compress -Depth 12|Add-Content -LiteralPath (Join-Path $d 'lab-events.jsonl') -Encoding UTF8}
function Provider($a,$d,[switch]$WhatIfOnly){$p=Paths $d;$x=@{Action=$a;StatePath=$p.Provider;LogPath=$p.ProviderLog};if($WhatIfOnly){& $ProviderPath @x -WhatIf}else{& $ProviderPath @x}}
function ResumeTask{Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue}
function RegisterResume($d){if(ResumeTask){throw 'Continuation task collision.'};$exe=(Get-Command powershell.exe -ErrorAction Stop).Source;$args="-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$d`" -EvidenceRoot `"$EvidenceRoot`" -ProviderPath `"$ProviderPath`"";$a=New-ScheduledTaskAction -Execute $exe -Argument $args;$u=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $u;$pr=New-ScheduledTaskPrincipal -UserId $u -LogonType Interactive -RunLevel Highest;$s=New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit(New-TimeSpan -Minutes 20);if($PSCmdlet.ShouldProcess($TaskName,'Register reversible continuation task')){Register-ScheduledTask -TaskName $TaskName -Action $a -Trigger $t -Principal $pr -Settings $s|Out-Null}}
function RemoveResume($d){if(ResumeTask){if($PSCmdlet.ShouldProcess($TaskName,'Remove continuation task')){Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false;Log $d 'continuation-task-removed' 'pass' @{task=$TaskName}}}}
function Protected{$svc=@();foreach($n in 'WinDefend','mpssvc','wuauserv','UsoSvc','BITS','Tailscale','TermService'){try{$s=Get-Service $n -ErrorAction Stop;$svc+=[pscustomobject]@{name=$n;status="$($s.Status)";startType="$($s.StartType)"}}catch{$svc+=[pscustomobject]@{name=$n;status='absent';startType=$null}}};[pscustomobject]@{services=$svc;processes=@(Get-Process -ErrorAction SilentlyContinue|Where-Object{$_.ProcessName-match'(?i)omnissa|horizon|msrdc|mstsc|tailscale|windowsapp'}|Select-Object ProcessName,Id,Responding)}}
function RegState($ps){$path=[string]$ps.entry.Path;$name=[string]$ps.entry.Name;if(!(Test-Path -LiteralPath $path)){return[pscustomobject]@{present=$false;kind=$null;data=$null}};$k=Get-Item -LiteralPath $path;if(!($k.GetValueNames()-contains$name)){return[pscustomobject]@{present=$false;kind=$null;data=$null}};[pscustomobject]@{present=$true;kind=$k.GetValueKind($name).ToString();data=[string]$k.GetValue($name,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)}}
function AssertBase($ps){$r=RegState $ps;if(!$r.present-or$r.kind-ne[string]$ps.entry.Kind-or$r.data-ne[string]$ps.entry.Data){throw 'Baseline Logi Tune Run registration drift.'}}
function AssertTreat($ps){if((RegState $ps).present){throw 'Treatment Logi Tune Run registration reappeared.'}}
function Sample($phase,$ordinal,$d,$ps){$boot=BootUtc;$pb=Protected;$before=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$sys=@();$count=[int][math]::Ceiling($SampleSeconds/[double]$SampleIntervalSeconds);for($i=0;$i-lt$count;$i++){$c=Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'";$k=Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'";$sys+=[pscustomobject]@{cpu=[double]$c.PercentProcessorTime;disk=[double]$k.DiskBytesPersec};if($i-lt$count-1){Start-Sleep $SampleIntervalSeconds}};$after=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$e=Get-Process explorer -ErrorAction SilentlyContinue|Sort-Object StartTime|Select-Object -First 1;[ordered]@{schemaVersion=1;experiment=$Experiment;phase=$phase;ordinal=$ordinal;bootUtc=$boot.ToString('o');capturedUtc=(Get-Date).ToUniversalTime().ToString('o');registration=RegState $ps;desktopProxy=@{explorerPresent=[bool]$e;bootToExplorerStartMs=if($e){($e.StartTime.ToUniversalTime()-$boot).TotalMilliseconds}else{$null}};system=@{cpuMedianPercent=Med @($sys|ForEach-Object cpu);cpuMadPercent=Mad @($sys|ForEach-Object cpu);diskMedianBytesPerSec=Med @($sys|ForEach-Object disk);diskMadBytesPerSec=Mad @($sys|ForEach-Object disk)};protected=@{before=$pb;after=Protected};functionalEvidence=@{manualLogiTuneLaunch='needs-evidence';cameraAndHeadsetReadiness='needs-evidence';audioVideoDeviceReadiness='needs-evidence';protectedApplicationReadiness='needs-evidence'};instrumentation=@{collectorCpuDeltaMs=$after-$before;sampleCount=$sys.Count;sampleIntervalSeconds=$SampleIntervalSeconds}}}
function Summary($d){$r=@(Get-ChildItem $d -Filter 'run-*.json' -File|Sort-Object Name|ForEach-Object{RJ $_.FullName});$g=[ordered]@{};foreach($ph in 'Baseline','Treatment'){$x=@($r|Where-Object phase -eq $ph);$g[$ph]=@{runs=$x.Count;bootToExplorerStartMs=@{median=Med @($x|ForEach-Object{$_.desktopProxy.bootToExplorerStartMs});mad=Mad @($x|ForEach-Object{$_.desktopProxy.bootToExplorerStartMs})};cpuMedianPercent=@{median=Med @($x|ForEach-Object{$_.system.cpuMedianPercent});mad=Mad @($x|ForEach-Object{$_.system.cpuMedianPercent})};diskMedianBytesPerSec=@{median=Med @($x|ForEach-Object{$_.system.diskMedianBytesPerSec});mad=Mad @($x|ForEach-Object{$_.system.diskMedianBytesPerSec})}}};$rb=@($r|Where-Object phase -eq 'RollbackVerify'|Select-Object -Last 1);$o=[ordered]@{schemaVersion=1;experiment=$Experiment;generatedUtc=(Get-Date).ToUniversalTime().ToString('o');groups=$g;rollbackRebootVerified=($rb.Count-eq1-and[bool]$rb[0].registration.present);remainingEvidence=@('Manual Logi Tune launch','Camera and headset readiness','Audio/video device readiness','Timed Omnissa Windows App Remote Desktop and Tailscale readiness','Instrumentation qualification');limitations=@('bootToExplorerStartMs is an Explorer-start proxy','Physical performance and functionality remain needs-evidence')};WJ(Join-Path $d 'summary.json')$o;$o}
function Reboot($d){if($AllowAutomaticReboot){Log $d 'reboot-requested' 'pass' @{};Restart-Computer -Force}else{Log $d 'reboot-required' 'needs-evidence' @{};Write-Output 'Reboot required; continuation resumes at next interactive logon.'}}
Elevation;if(!(Test-Path -LiteralPath $ProviderPath)){throw 'EXP-052 provider missing.'}
try{switch($Action){
 'Start'{Ensure $EvidenceRoot;if(Test-Path $ActivePointer){throw 'Active EXP-052 run exists.'};$check=Provider Check $EvidenceRoot;Provider DryRun $EvidenceRoot|Out-Null;if($WhatIfPreference){$null=$PSCmdlet.ShouldProcess($TaskName,"Prepare $RunsPerArm matched boots");return $check};$d=Join-Path $EvidenceRoot((Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'));Ensure $d;$p=Paths $d;Provider Capture $d|Out-Null;WJ $p.Harness @{schemaVersion=1;phase='Baseline';completedRuns=0;runsPerArm=$RunsPerArm;lastBootUtc=$null;sampleSeconds=$SampleSeconds;sampleIntervalSeconds=$SampleIntervalSeconds};WJ $ActivePointer @{runDirectory=$d};RegisterResume $d;Log $d 'started' 'pass' @{runsPerArm=$RunsPerArm;sampleSeconds=$SampleSeconds};Reboot $d}
 'Continue'{$d=Dir;$p=Paths $d;$s=RJ $p.Harness;$ps=RJ $p.Provider;$boot=(BootUtc).ToString('o');if($s.lastBootUtc-eq$boot){throw 'Duplicate same-boot collection refused.'};if($s.phase-eq'RollbackVerify'){AssertBase $ps;$t=Sample RollbackVerify 1 $d $ps;WJ(Join-Path $d 'run-RollbackVerify-01.json')$t;Summary $d|Out-Null;RemoveResume $d;Remove-Item -LiteralPath $ActivePointer -Force;Log $d 'completed' 'pass' @{rollbackRebootVerified=$true};return RJ $p.Summary};if($s.phase-eq'Baseline'){AssertBase $ps}else{Provider VerifyReboot $d|Out-Null;AssertTreat $ps};$ord=[int]$s.completedRuns+1;$t=Sample $s.phase $ord $d $ps;WJ(Join-Path $d("run-{0}-{1:d2}.json"-f$s.phase,$ord))$t;$s.completedRuns=$ord;$s.lastBootUtc=$boot;if($ord-ge[int]$s.runsPerArm){if($s.phase-eq'Baseline'){Provider Apply $d|Out-Null;Provider Verify $d|Out-Null;$s.phase='Treatment';$s.completedRuns=0}elseif($s.phase-eq'Treatment'){Provider Rollback $d|Out-Null;$s.phase='RollbackVerify';$s.completedRuns=0}};WJ $p.Harness $s;Reboot $d}
 'Status'{$d=Dir;$p=Paths $d;[pscustomobject]@{RunDirectory=$d;Harness=RJ $p.Harness;Provider=RJ $p.Provider;ContinuationTaskPresent=[bool](ResumeTask)}}
 'Summarize'{$d=Dir;Summary $d}
 'Stop'{$d=Dir;$p=Paths $d;if(Test-Path $p.Provider){$ps=RJ $p.Provider;if(!(RegState $ps).present){Provider Rollback $d|Out-Null}};RemoveResume $d;if(Test-Path $ActivePointer){Remove-Item -LiteralPath $ActivePointer -Force};Log $d 'stopped' 'pass' @{rollbackAttempted=$true}}
}}catch{try{if($RunDirectory-or(Test-Path $ActivePointer)){$d=Dir;Log $d 'failure' 'failure' @{message=$_.Exception.Message;type=$_.Exception.GetType().FullName}}}catch{};throw}
